CREATE TABLE task_event_dead_letters (
 id char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,event_id char(36) CHARACTER SET ascii COLLATE ascii_bin,tenant_id char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,workspace_id char(36) CHARACTER SET ascii COLLATE ascii_bin,node_id char(36) CHARACTER SET ascii COLLATE ascii_bin,task_id char(36) CHARACTER SET ascii COLLATE ascii_bin,generation integer,delivery_id char(36) CHARACTER SET ascii COLLATE ascii_bin,
 kind varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(kind IN('publish','consume','expiry','poison')),outcome_unknown boolean NOT NULL CHECK(outcome_unknown IN(0,1)),
 broker_identity char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(broker_identity,'^[a-f0-9]{64}$','c')),broker_sequence decimal(20,0),consumer_name varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 envelope_sha256 char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(envelope_sha256,'^[a-f0-9]{64}$','c')),error_code varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 retry_actor char(36) CHARACTER SET ascii COLLATE ascii_bin,retry_key char(36) CHARACTER SET ascii COLLATE ascii_bin,retry_reason varchar(500),retry_fingerprint varbinary(32) CHECK(retry_fingerprint IS NULL OR octet_length(retry_fingerprint)=32),retry_delivery_id char(36) CHARACTER SET ascii COLLATE ascii_bin,retry_generation integer,retried_at datetime(6),
 created_at datetime(6) NOT NULL,
 UNIQUE(event_id,generation),UNIQUE(delivery_id),UNIQUE(broker_identity,broker_sequence,consumer_name),UNIQUE(retry_actor,retry_key),
 FOREIGN KEY(tenant_id,workspace_id,node_id,task_id,event_id) REFERENCES task_event_outbox(tenant_id,workspace_id,node_id,task_id,id),FOREIGN KEY(retry_actor) REFERENCES users(id),
 CONSTRAINT task_event_dead_letters_scope CHECK((event_id IS NOT NULL AND workspace_id IS NOT NULL AND node_id IS NOT NULL AND task_id IS NOT NULL AND generation IS NOT NULL AND generation>=1 AND delivery_id IS NOT NULL) OR (event_id IS NULL AND workspace_id IS NULL AND node_id IS NULL AND task_id IS NULL AND generation IS NULL AND delivery_id IS NULL AND kind='poison')),
 CONSTRAINT task_event_dead_letters_sequence CHECK(broker_sequence IS NULL OR broker_sequence BETWEEN 1 AND 18446744073709551615),
 CONSTRAINT task_event_dead_letters_retry CHECK((retry_actor IS NULL AND retry_key IS NULL AND retry_reason IS NULL AND retry_fingerprint IS NULL AND retry_delivery_id IS NULL AND retry_generation IS NULL AND retried_at IS NULL) OR (event_id IS NOT NULL AND retry_actor IS NOT NULL AND retry_key IS NOT NULL AND retry_reason IS NOT NULL AND retry_fingerprint IS NOT NULL AND retry_delivery_id IS NOT NULL AND retry_generation IS NOT NULL AND retry_generation>generation AND retried_at IS NOT NULL AND retried_at>=created_at))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;